What were the 3 products with the fewest incidents in June of last year? 

{
  "sql": "SELECT d37208_product_class_name, SUM(d37208_incident_count) AS 工单数量 FROM t_data_assistant_incident WHERE d37208_incident_month = '2022-06' GROUP BY d37208_product_class_name ORDER BY 工单数量 ASC LIMIT 3"
}

